from ute_common_store import Store
from ute_common_interface.scope import ScopeController
from ute_fsmaccess import ute_fsmaccess
from taf.sbts.oam.coam.admin import admin
from contextlib import contextmanager

from .fsmr4 import Fsm4TddTtiTrace, Fsm4FddTtiTrace, Fsm4MixedFddTddTtiTrace
from .fsmr3 import Fsm3TddTtiTrace, Fsm3FddTtiTrace
from .TTITraceServer import TtiTraceServer
from .xml import LocalXML

import logging


class ta_ttitrace(ScopeController):
    """Class provide mechanism for ttistream capturing on local or remote machine interface.

       This library supports multiple setups where each setup can be specified by **alias** argument for every keyword.

        Examples are available in attached Robot Framework example files

    Keywords
    ********
    """
    ttitrace_class = {'FSMr3': {'FDD': Fsm3FddTtiTrace, 'TDD': Fsm3TddTtiTrace},
                      'FSMr4': {'FDD': Fsm4FddTtiTrace, 'TDD': Fsm4TddTtiTrace, 'mixed_FDD_TDD': Fsm4MixedFddTddTtiTrace},
                      'FSMrALL': {'SWALL': TtiTraceServer}}

    def __init__(self):
        super(ta_ttitrace, self).__init__()
        self.store = Store()
        self.ssh_client = None

    def setup_ttitrace(self, host_ip='localhost',
                       stream_path=None,
                       tracer_path=None,
                       ip_addr='192.168.255.129',
                       timeout=900,
                       log_path='/tmp',
                       **kwargs):
        """Setup ttitrace library

        :param string host_ip:      IP address of the remote machine.
        :param stream_path:         Path to directory where ttistream is located.
        :param trace_path:          Path to directory where ttitrace is located.
        :param ip_addr:             eNB IP address
        :param timeout:             Execution timeout to be used in executor
        :param log_path:            Directory for output files to be moved. Please use unique log_path.


        :Supported SSH parameters are available via kwargs:
            * **ssh_username**   (string)  - Username valid for SSH authentication. Default is 'ute'.
            * **ssh_password**   (string)  - Password valid for SSH authentication. Default is 'ute'.
            * **ssh_port**       (integer) - SSH service port available on specified machine. Default is 22.
            * **ssh_prompt**     (string)  - SH prompt available after log in. Default is '$ '.

        It is possible to change the kwargs parameters by using syntax like in the example below:

        ::

                Some keyword     ssh_username=test_user    ssh_password=test_pass    ssh_port=22    ssh_prompt=\\$
        """
        self._host_ip = host_ip
        self._log_path = log_path
        self._ssh_username = kwargs.get('ssh_username', 'ute')
        self._ssh_password = kwargs.get('ssh_password', 'ute')
        self._ssh_prompt = kwargs.get('ssh_prompt', '$ ')
        cells_sw_type = ''
        hw_type = self._get_hw_type(ip_addr)
        if hw_type == 'FSMrALL':
            sw_type = 'SWALL'
        else:
            scfc = self._get_scf(ip_addr)
            sw_type = self._get_sw_type(scfc)
            logging.info("sw_type:{}".format(sw_type))
            if sw_type == 'mixed_FDD_TDD':
                cells_sw_type = self._get_cells_technology(scfc)
            logging.info(cells_sw_type)
        logging.info("hw_type:{}".format(hw_type))
        sw_version = self._get_enb_sw_version(ip_addr)
        ttitrace = self.ttitrace_class[hw_type][sw_type](host_ip=host_ip,
                                                         ssh_username=self._ssh_username,
                                                         ssh_password=self._ssh_password,
                                                         ssh_prompt=self._ssh_prompt,
                                                         ssh_port=int(kwargs.get('ssh_port', 22)),
                                                         stream_path=stream_path,
                                                         tracer_path=tracer_path,
                                                         ip_addr=ip_addr,
                                                         timeout=timeout,
                                                         log_path=log_path,
                                                         sw_version=sw_version,
                                                         cells_sw_type=cells_sw_type)
        self.store.add(ttitrace, alias=kwargs.get('alias'))

    def teardown_ttitrace(self, **kwargs):
        """Close and cleanup ttitrace.
        """
        ttitrace = self.store.get(alias=kwargs.get('alias'))
        ttitrace.stop_server()
        ttitrace.collect_logs()
        ttitrace.close_ssh_connection()
        self.store.remove(alias=kwargs.get('alias'))

    def teardown_all_aliases_for_ttitrace(self):
        """Close and Cleanup all tshark aliases.
        """
        self._out_of_scope()

    def start_tti_stream(self, core=None, **kwargs):
        """Start capturing ttiStream
        :param string core:     -c for ttiStream / onlineTtiStream_64 / remote_execute_cli_debian

        |

        :kwargs should be used for optional switches:
            * **ip_addr** (string)      - -n for ttiStream
                                        - -i for onlineTtiStream_64
            * **port** (string)         - -P for ttiStream / onlineTtiStream_64
                                        - -p for cli_aatrace_utility_debian
            * **task** (string)         - -t for ttiStream
            * **filesize** (string)     - -m for ttiStream / onlineTtiStream_64
            * **prefix** (string)       - -o for ttiStream / onlineTtiStream_64
            * **duration** (string)     - -u for ttiStream

        |

        """
        ttitrace_instance = self.store.get(alias=kwargs.get('alias'))
        param = self._create_param_dict(kwargs)
        ttitrace_instance.start_tti_stream(core=core, param=param)

    def stop_tti_stream(self, lrc=None, **kwargs):
        """Stop capturing ttiStream

        :return list:        list of names of the created dat files
        """
        return self.store.get(alias=kwargs.get('alias')).stop_tti_stream(lrc=lrc)

    def stop_tti_stream_and_convert_to_txt(self, nb=False, ext='txt', lrc=None, **kwargs):
        """Stop capturing ttiStream and automatically converts the dat files to txt
        :param bool nb:     enable NB TTI trace parsing
        :param string ext:  output file extension. Default is .txt.
        :return list:       list of names of successfully converted dat files
        """
        return self.store.get(alias=kwargs.get('alias')).stop_tti_stream_and_convert_to_text(nb=nb, ext=ext, lrc=lrc)

    def convert_dat_to_txt(self, dat_file, output=None, nb=False, **kwargs):
        """Convert dat file to txt file using TtiTracer

        :param string dat_file:    input dat file name
        :param string output:      output txt file name defaults to <dat_file>.txt
        :param bool nb:            enable NB TTI trace parsing
        :return string:            output file name or empty string if no txt file created
        """
        return self.store.get(alias=kwargs.get('alias')).convert_dat_to_text(source=dat_file, destination=output, nb=nb)

    def get_tti_ul_node(self, lcr=None, **kwargs):
        """Returns the TTI_UL Node value for a specified local cell resource id

        :param string lcr:      local cell resource id
        :return string:                tti UL Node
        """
        lcr = str(lcr) if lcr is not None else lcr
        return self.store.get(alias=kwargs.get('alias')).get_tti_ul_node(lcr=lcr)

    def get_tti_dl_node(self, lcr=None, **kwargs):
        """Returns the TTI_DL Node value for a specified local cell resource id

        :param string lcr:      local cell resource id
        :return string:                tti DL Node
        """
        lcr = str(lcr) if lcr is not None else lcr
        return self.store.get(alias=kwargs.get('alias')).get_tti_dl_node(lcr=lcr)

    def _create_param_dict(self, params):
        params.pop('alias', None)
        return params

    def _out_of_scope(self):
        for key in self.store.aliases:
            self.teardown_ttitrace(alias=key)

    def _get_enb_sw_version(self, ip_addr):
        with self._new_fsmaccess_session(ip_addr) as fsmaccess:
            return fsmaccess.get_enb_sw_version()

    def _get_hw_type(self, ip_addr):
        try:
            with self._new_fsmaccess_session(ip_addr) as fsmaccess:
                hw_version = fsmaccess.get_enb_hw_version()
                if "FSM" in hw_version and int(hw_version[-1]) > 4:
                    hw_version = 'FSMr4'
                return hw_version
        except Exception as e:
            return self._mapping_hw_type(str(e))

    def _mapping_hw_type(self, e):
        new_hw_type = ["ASIK", "ASIL", "ASIM",
                       "ABIL", "ABIN", "ABIO", "ABIP",
                       "ASOD", "ASOE", "ASOF", "ASOy"]
        for one in new_hw_type:
            if one in e:
                return "FSMr4"
        raise Exception(e)

    def _get_sw_type(self, scfc_content):
        cell_technology = ['TDD', 'FDD', 'mixed_FDD_TDD']
        inst = LocalXML()
        xpath = ".//p[@name='supportedCellTechnology']"
        element = inst.get_element_text(inst.parse_xml(scfc_content), xpath=xpath)
        if element:
            if element in cell_technology:
                return element
        logging.info(scfc_content)
        raise Exception('Do not get correct Cell Technology in scfc.')

    def _get_scf(self, host):
        try:
            bts_coam = admin()
            rmt_host = None if self._host_ip == 'localhost' else self._host_ip
            bts_coam.setup_admin(bts_host=host, bts_port=443, timeout=15, remote_host=rmt_host,
                                 admin_api_log_dir=self._log_path, remote_host_username=self._ssh_username,
                                 remote_host_password=self._ssh_password, name="tti_z")
            return bts_coam.get_scf(connection="tti_z")
        except Exception as e:
            raise Exception(e)
        finally:
            bts_coam.teardown(connection="tti_z")

    def _get_cells_technology(self, scfc_content):
        cell_techology = {}
        try:
            parser = LocalXML()
            mObjs = parser.get_elements(parser.parse_xml(scfc_content), "*/managedObject")
            lncels = [obj for obj in mObjs if obj.attrib["class"] == "LNCEL" or obj.attrib["class"] == "NOKLTE:LNCEL"]
            for lnce in lncels:
                iterator = list(lnce.iter())
                for i in iterator:
                    if "p" == i.tag and i.attrib["name"] == "lcrId":
                        localCellId = parser.get_element_text(i)
                    if "p" == i.tag and i.attrib["name"] == "cellTechnology":
                        cellTec = parser.get_element_text(i)
                cell_techology[localCellId] = cellTec
        except Exception as e:
            logging.debug(e)
        return cell_techology

    @contextmanager
    def _new_fsmaccess_session(self, host):
        fsmaccess = ute_fsmaccess()
        fsmaccess.setup_enb_fsm_access(remote_host=self._host_ip,
                                       remote_ssh_user=self._ssh_username,
                                       remote_ssh_pass=self._ssh_password,
                                       remote_ssh_prompt=self._ssh_prompt,
                                       host=host, prompt=' >', fallback_prompt='#')
        try:
            yield fsmaccess
        finally:
            fsmaccess.teardown_enb_fsm_access()
